package by.bsuir.gateway;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.core.annotation.Order; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfiguration {
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/graphiql/**","/graphql").permitAll().anyRequest().denyAll()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}
}
@Component class JwtFilter extends OncePerRequestFilter {
 private final SecretKey key; private final String issuer; private final GrpcClients clients;
 JwtFilter(@Value("${security.jwt.secret}")String secret,@Value("${security.jwt.issuer:repair-auth-service}")String issuer,GrpcClients clients){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.issuer=issuer;this.clients=clients;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String header=req.getHeader(HttpHeaders.AUTHORIZATION);if(header==null||!header.startsWith("Bearer ")){chain.doFilter(req,res);return;}try{Claims c=Jwts.parser().verifyWith(key).requireIssuer(issuer).build().parseSignedClaims(header.substring(7)).getPayload();String sid=c.get("sid",String.class);var access=clients.call(()->clients.deadline(clients.identity).validateSession(by.bsuir.repair.contract.SessionRequest.newBuilder().setSessionId(sid).build()));if(!access.getActive())throw new IllegalArgumentException("Session expired");var principal=new AuthPrincipal(c.getSubject(),c.get("email",String.class),c.get("role",String.class),sid);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(principal,null,List.of(new SimpleGrantedAuthority("ROLE_"+principal.role()))));chain.doFilter(req,res);}catch(Exception e){SecurityContextHolder.clearContext();res.setStatus(401);res.setContentType("application/json");res.getWriter().write("{\"error\":\"UNAUTHENTICATED\",\"message\":\"JWT or session is invalid\"}");}}
}
